  1668    if (resp_hdr == NULL)
  1669      return -1;
  1670  
  1671    /* CDXJ status/mime (from the caller's status and the response Content-Type).
  1672     */
  1673    snprintf(statusbuf, sizeof(statusbuf), "%d", statuscode);
  1674    http_header_value(resp_hdr, "Content-Type", mimebuf, sizeof(mimebuf));
  1675  
  1676    /* A payload exists (for digesting) unless this is a bodyless 304. */
  1677    has_payload = (body_len > 0 && (body != NULL || body_path != NULL) &&
  1678                   !is_update_unchanged);
