  1680    /* Payload digest drives identical-payload-digest dedup (OpenSSL only). */
  1681    have_pdig =
  1682        has_payload ? payload_digest_b32(body, body_len, body_path, pdig) : 0;
  1683  
  1684    if (is_update_unchanged) {
  1685      is_revisit = 1;
  1686      profile = "http://netpreserve.org/warc/1.1/revisit/server-not-modified";
  1687      /* Served from cache: the payload sits in the previous archive, not here. */
  1688      w->unbacked_revisits++;
