  1690      void *prev = NULL;
  1691      if (coucal_read_pvoid(w->seen, pdig, &prev) && prev != NULL) {
  1692        char *slot = (char *) prev;
  1693        char *sep = strchr(slot, '\001');
  1694        is_revisit = 1;
  1695        profile =
  1696            "http://netpreserve.org/warc/1.1/revisit/identical-payload-digest";
  1697        if (sep != NULL) {
  1698          size_t n = (size_t) (sep - slot);
  1699          if (n < sizeof(refers_buf)) {
  1700            memcpy(refers_buf, slot, n);
  1701            refers_buf[n] = '\0';
  1702            refers_uri = refers_buf;
  1703            refers_date = sep + 1;
  1704          }
  1705        }
  1706      }
  1707    }
