  1713    /* Full response rewrites Content-Length and keeps Content-Encoding verbatim
  1714       (see normalize_http_headers); a revisit keeps the original headers. */
  1715    memset(&http, 0, sizeof(http));
  1716    if (normalize_http_headers(resp_hdr, emit_body ? (long long) body_len : -1,
  1717                               &http) != 0) {
  1718      wbuf_free(&http);
  1719      return -1;
  1720    }
  1721  
  1722    /* Response first: its id links the request via WARC-Concurrent-To. A revisit
  1723       is a deliberate dedup, not a truncation, so tag WARC-Truncated only on a
  1724       full (body-carrying) response. */
  1725    resp_id[0] = '\0';
  1726    if (warc_emit(w, is_revisit ? "revisit" : "response",
  1727                  "application/http;msgtype=response", target_uri, ip, NULL,
  1728                  refers_uri, refers_date, profile, have_pdig ? pdig : NULL,
  1729                  emit_body ? warc_truncated_reason(truncated) : NULL, statusbuf,
  1730                  mimebuf, 1, http.data, http.len, emit_body, body, body_len,
  1731                  body_path, resp_id) != 0) {
  1732      wbuf_free(&http);
  1733      return -1;
  1734    }
  1735    wbuf_free(&http);
